package com.nigson.commerce.reward;

import java.net.URI;
import java.math.BigDecimal;
import java.security.SecureRandom;
import java.sql.Timestamp;
import java.time.Clock;
import java.util.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.transaction.support.TransactionSynchronization;
import org.springframework.transaction.support.TransactionSynchronizationManager;
import com.nigson.commerce.platform.AuditWriter;
import com.nigson.commerce.platform.PlatformStore;
import com.nigson.shared.events.EventCodec;
import com.nigson.shared.problem.*;
import com.nigson.shared.security.ActorAssertion;
import tools.jackson.databind.JsonNode;

/** Commerce-owned append-only reward ledger and referral commands. */
public final class RewardService {
 private static final SecureRandom RANDOM=new SecureRandom();
 private final JdbcTemplate jdbc;private final PlatformStore commands;private final AuditWriter audit;private final Clock clock;private final String referralBase;private final io.micrometer.core.instrument.MeterRegistry metrics;private final int phase;private final String distributorEntitlement;
 public RewardService(JdbcTemplate jdbc,PlatformStore commands,AuditWriter audit,Clock clock,String referralBase,int phase,io.micrometer.core.instrument.MeterRegistry metrics){this(jdbc,commands,audit,clock,referralBase,phase,metrics,"");}
 public RewardService(JdbcTemplate jdbc,PlatformStore commands,AuditWriter audit,Clock clock,String referralBase,int phase,io.micrometer.core.instrument.MeterRegistry metrics,String distributorEntitlement){this.jdbc=jdbc;this.commands=commands;this.audit=audit;this.clock=clock;this.referralBase=base(referralBase);this.phase=phase;this.metrics=metrics;this.distributorEntitlement=distributorEntitlement==null?"":distributorEntitlement;if(phase<1||phase>5||!this.distributorEntitlement.isEmpty()&&!this.distributorEntitlement.matches("[A-Z][A-Z0-9_]{1,39}"))throw new IllegalArgumentException("PRODUCT_PHASE_INVALID");}
 private static String base(String value){if(value==null||value.isBlank())return "";try{URI u=URI.create(value);if(!"https".equalsIgnoreCase(u.getScheme())||u.getHost()==null||u.getUserInfo()!=null||u.getQuery()!=null||u.getFragment()!=null||!u.getPath().matches("/[A-Za-z0-9/_-]{0,120}"))throw new IllegalArgumentException();return value.endsWith("/")?value:value+"/";}catch(RuntimeException invalid){throw new IllegalArgumentException("REWARD_REFERRAL_BASE_INVALID");}}
 private void current(ActorAssertion.Actor actor){if(actor==null||actor.party()==null)throw new Problem.Failure(ProblemCode.AUTH_REQUIRED);if(phase<2)throw new Problem.Failure(ProblemCode.FEATURE_DISABLED);Integer count=jdbc.queryForObject("SELECT count(*) FROM commerce.party WHERE id=? AND identity_issuer=? AND identity_subject=? AND status='ACTIVE'",Integer.class,actor.party(),actor.identityIssuer(),actor.identitySubject());if(count==null||count!=1||!actor.roles().contains("CUSTOMER"))throw new Problem.Failure(ProblemCode.ACCESS_DENIED);}
 public RewardValues.Ledger ledger(ActorAssertion.Actor actor){current(actor);var entries=jdbc.query("SELECT e.id,e.kind,e.amount,e.currency_code,e.created_at,c.minor_unit FROM commerce.reward_entry e JOIN commerce.currency c ON c.code=e.currency_code WHERE e.party_id=? ORDER BY e.created_at DESC,e.id DESC",(r,n)->new RewardValues.Entry(r.getObject(1,UUID.class),r.getString(2),money(r.getBigDecimal(3),r.getInt(6)),r.getString(4),r.getTimestamp(5).toInstant()),actor.party());var balances=jdbc.query("SELECT e.currency_code,sum(CASE WHEN e.kind IN ('EARN','DEALER_ISSUE') THEN e.amount WHEN e.kind IN ('REDEEM','EXPIRE','REVERSE') THEN -e.amount ELSE 0 END),c.minor_unit FROM commerce.reward_entry e JOIN commerce.currency c ON c.code=e.currency_code WHERE e.party_id=? AND e.available_at<=? AND (e.expires_at IS NULL OR e.expires_at>?) GROUP BY e.currency_code,c.minor_unit ORDER BY e.currency_code",(r,n)->new RewardValues.Balance(r.getString(1),money(r.getBigDecimal(2),r.getInt(3))),actor.party(),Timestamp.from(clock.instant()),Timestamp.from(clock.instant()));return new RewardValues.Ledger(balances,entries);}
 private String money(java.math.BigDecimal amount,int minor){try{return amount.setScale(minor,java.math.RoundingMode.UNNECESSARY).toPlainString();}catch(ArithmeticException invalid){throw RewardValues.rule();}}
 public RewardValues.Referral referral(ActorAssertion.Actor actor){current(actor);var rows=jdbc.query("SELECT c.code,(SELECT count(*) FROM commerce.referral_attribution a WHERE a.referrer_party_id=c.party_id AND a.state='QUALIFIED') FROM commerce.referral_code c WHERE c.party_id=? AND c.active",(r,n)->new Object[]{r.getString(1),r.getInt(2)},actor.party());if(rows.size()!=1)throw new Problem.Failure(ProblemCode.NOT_FOUND);if(referralBase.isEmpty())throw new Problem.Failure(ProblemCode.FEATURE_DISABLED);return new RewardValues.Referral((String)rows.getFirst()[0],referralBase+(String)rows.getFirst()[0],(Integer)rows.getFirst()[1]);}
 public RewardValues.Referral createReferral(ActorAssertion.Actor actor,JsonNode body,String key,UUID correlation){current(actor);RewardValues.emptyObject(body);if(referralBase.isEmpty())throw new Problem.Failure(ProblemCode.FEATURE_DISABLED);ApiValues.idempotencyKey(key);if(correlation==null||correlation.equals(new UUID(0,0)))throw ApiValues.invalid();var saved=commands.executeLocal(actor.party().toString(),"API-161",key,EventCodec.JSON.createObjectNode(),db->{lockCurrent(actor);var existing=jdbc.query("SELECT code FROM commerce.referral_code WHERE party_id=? FOR UPDATE",(r,n)->r.getString(1),actor.party());boolean created=existing.isEmpty();String code;if(created){code=newCode();jdbc.update("INSERT INTO commerce.referral_code(id,created_by,updated_by,party_id,code,active) VALUES (?,?,?,?,?,true) ON CONFLICT(party_id) DO NOTHING",EventCodec.uuid7(clock.instant()),actor.party().toString(),actor.party().toString(),actor.party(),code);existing=jdbc.query("SELECT code FROM commerce.referral_code WHERE party_id=?",(r,n)->r.getString(1),actor.party());if(existing.size()!=1)throw new Problem.Failure(ProblemCode.INTERNAL_ERROR);code=existing.getFirst();}else code=existing.getFirst();int count=jdbc.queryForObject("SELECT count(*) FROM commerce.referral_attribution WHERE referrer_party_id=? AND state='QUALIFIED'",Integer.class,actor.party());if(created)audit.append(actor.party().toString(),AuditValues.ActorKind.USER,AuditValues.Action.REFERRAL_CODE_CREATE,AuditValues.Resource.REFERRAL,EventCodec.uuid7(clock.instant()),correlation,AuditValues.Reason.OPERATOR_REQUEST,null,Map.of("created",true),null);var response=new RewardValues.Referral(code,referralBase+code,count);if(created)TransactionSynchronizationManager.registerSynchronization(new TransactionSynchronization(){public void afterCommit(){metrics.counter("nigson.reward.commands","operation","REFERRAL_CODE").increment();}});return new PlatformStore.Response(created?201:200,EventCodec.JSON.valueToTree(response),actor.party());});return EventCodec.JSON.treeToValue(saved.body(),RewardValues.Referral.class);}
 private String newCode(){byte[] data=new byte[15];RANDOM.nextBytes(data);return HexFormat.of().withUpperCase().formatHex(data);}
 public RewardValues.Attribution attribute(ActorAssertion.Actor actor,JsonNode body,String key,UUID correlation){current(actor);String code=RewardValues.referralCode(body);ApiValues.idempotencyKey(key);if(correlation==null||correlation.equals(new UUID(0,0)))throw ApiValues.invalid();var request=EventCodec.JSON.createObjectNode().put("code",code);var saved=commands.executeLocal(actor.party().toString(),"API-064",key,request,db->{lockCurrent(actor);if(actor.party().equals(new UUID(0,0)))throw ApiValues.invalid();if(Boolean.TRUE.equals(jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM commerce.sales_order WHERE party_id=? AND payment_status IN ('PAID','PARTIALLY_REFUNDED','REFUNDED'))",Boolean.class,actor.party())))throw RewardValues.rule();var codeRows=jdbc.query("SELECT c.party_id FROM commerce.referral_code c JOIN commerce.party p ON p.id=c.party_id AND p.status='ACTIVE' WHERE c.code=? AND c.active FOR SHARE OF c,p",(r,n)->r.getObject(1,UUID.class),code);if(codeRows.size()!=1||actor.party().equals(codeRows.getFirst()))throw RewardValues.rule();var rules=jdbc.query("SELECT r.id,r.parameters::text FROM commerce.promotion_rule r JOIN commerce.market m ON m.id=r.market_id WHERE r.kind='REFERRAL' AND r.enabled AND r.starts_at<=? AND r.ends_at>? AND m.code='NG' AND m.enabled ORDER BY r.id FOR SHARE OF r,m",(r,n)->new Object[]{r.getObject(1,UUID.class),r.getString(2)},Timestamp.from(clock.instant()),Timestamp.from(clock.instant()));if(rules.size()!=1)throw new Problem.Failure(ProblemCode.FEATURE_DISABLED);validateReferralRule(parse((String)rules.getFirst()[1]));UUID id=EventCodec.uuid7(clock.instant());try{jdbc.update("INSERT INTO commerce.referral_attribution(id,created_by,updated_by,referrer_party_id,referred_party_id,rule_id,state) VALUES (?,?,?,?,?,?,'ATTRIBUTED')",id,actor.party().toString(),actor.party().toString(),codeRows.getFirst(),actor.party(),rules.getFirst()[0]);}catch(org.springframework.dao.DuplicateKeyException exists){throw RewardValues.rule();}audit.append(actor.party().toString(),AuditValues.ActorKind.USER,AuditValues.Action.REFERRAL_ATTRIBUTION,AuditValues.Resource.REFERRAL,id,correlation,AuditValues.Reason.OPERATOR_REQUEST,null,Map.of("created",true),null);TransactionSynchronizationManager.registerSynchronization(new TransactionSynchronization(){public void afterCommit(){metrics.counter("nigson.reward.commands","operation","ATTRIBUTION").increment();}});return new PlatformStore.Response(201,EventCodec.JSON.valueToTree(new RewardValues.Attribution(id,"ATTRIBUTED")),id);});return EventCodec.JSON.treeToValue(saved.body(),RewardValues.Attribution.class);}
 private JsonNode json(String value){try{return EventCodec.JSON.readTree(value);}catch(Exception invalid){throw RewardValues.rule();}}
 private int integer(JsonNode value,String field,int min,int max){if(!value.path(field).isIntegralNumber()||!value.path(field).canConvertToInt())throw RewardValues.rule();int n=value.path(field).intValue();if(n<min||n>max)throw RewardValues.rule();return n;}
 private void lockCurrent(ActorAssertion.Actor actor){var rows=jdbc.query("SELECT id FROM commerce.party WHERE id=? AND identity_issuer=? AND identity_subject=? AND status='ACTIVE' FOR UPDATE",(r,n)->r.getObject(1,UUID.class),actor.party(),actor.identityIssuer(),actor.identitySubject());if(rows.size()!=1)throw new Problem.Failure(ProblemCode.ACCESS_DENIED);}
 private JsonNode parse(String json){try{return EventCodec.JSON.readTree(json);}catch(Exception invalid){throw RewardValues.rule();}}
 private void validateReferralRule(JsonNode p){RewardValues.exact(p,Set.of("schemaVersion","minimumSettledSpend","referrerReward","referredReward","holdDays","expiresDays","maximumRewardsPerReferrer","refundMode"));if(!p.path("schemaVersion").isIntegralNumber()||p.path("schemaVersion").asInt()!=1||!p.path("minimumSettledSpend").isString()||!p.path("referrerReward").isString()||!p.path("referredReward").isString()||!p.path("holdDays").isIntegralNumber()||!p.path("expiresDays").isIntegralNumber()||!p.path("maximumRewardsPerReferrer").isIntegralNumber()||!p.path("refundMode").isString()||!Set.of("PROPORTIONAL","FULL_ON_ANY_REFUND").contains(p.path("refundMode").asString()))throw RewardValues.rule();try{RewardValues.nonnegative(p.path("minimumSettledSpend").asString(),2);RewardValues.amount(p.path("referrerReward").asString(),2);RewardValues.nonnegative(p.path("referredReward").asString(),2);int hold=p.path("holdDays").intValue(),expires=p.path("expiresDays").intValue(),limit=p.path("maximumRewardsPerReferrer").intValue();if(hold<0||hold>365||expires<1||expires>3650||limit<1)throw RewardValues.rule();}catch(RuntimeException invalid){if(invalid instanceof Problem.Failure failure)throw failure;throw RewardValues.rule();}}
 public RewardValues.DealerReward issueDealer(ActorAssertion.Actor actor,UUID organization,JsonNode body,String key,UUID correlation){
  if(actor==null||actor.party()==null)throw new Problem.Failure(ProblemCode.AUTH_REQUIRED);
  if(phase<3)throw new Problem.Failure(ProblemCode.FEATURE_DISABLED);
  if(!actor.roles().contains("SALES")||actor.organization()!=null||!Boolean.TRUE.equals(jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM commerce.party p JOIN commerce.staff_role_assignment r ON r.party_id=p.id AND r.role='SALES' AND r.revoked_at IS NULL WHERE p.id=? AND p.identity_issuer=? AND p.identity_subject=? AND p.status='ACTIVE')",Boolean.class,actor.party(),actor.identityIssuer(),actor.identitySubject())))throw new Problem.Failure(ProblemCode.ACCESS_DENIED);
  if(body==null||!body.isObject()||body.size()!=3||!body.has("ruleId")||!body.get("ruleId").isTextual()||!body.has("amount")||!body.get("amount").isTextual()||!body.has("reason")||!body.get("reason").isTextual())throw ApiValues.invalid();
  UUID rule;try{rule=UUID.fromString(body.get("ruleId").asString());}catch(IllegalArgumentException invalid){throw ApiValues.invalid();}
  String raw=body.get("amount").asString(),reason=body.get("reason").asString();BigDecimal requested=RewardValues.amount(raw,2);
  if(reason.strip().length()<10||reason.length()>300||reason.codePoints().anyMatch(c->Character.isISOControl(c)||Character.getType(c)==Character.FORMAT)||organization==null||organization.equals(new UUID(0,0))||correlation==null||correlation.equals(new UUID(0,0)))throw ApiValues.invalid();
  ApiValues.idempotencyKey(key);var request=EventCodec.JSON.valueToTree(Map.of("organizationId",organization,"ruleId",rule,"amount",raw,"reason",reason));
  try{var saved=commands.executeLocal(actor.party().toString(),"API-065",key,request,db->{jdbc.execute("SET LOCAL lock_timeout='500ms'");jdbc.execute("SET LOCAL statement_timeout='2s'");var orgs=jdbc.query("SELECT o.id,o.status FROM commerce.organization o WHERE o.id=? FOR UPDATE",(r,n)->new Object[]{r.getObject(1,UUID.class),r.getString(2)},organization);if(orgs.size()!=1)throw new Problem.Failure(ProblemCode.NOT_FOUND);if(!"ACTIVE".equals(orgs.getFirst()[1])||distributorEntitlement.isEmpty()||!Boolean.TRUE.equals(jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM commerce.account_entitlement WHERE organization_id=? AND entitlement=? AND status='ACTIVE')",Boolean.class,organization,distributorEntitlement)))throw new Problem.Failure(ProblemCode.ACCESS_DENIED);
   var rules=jdbc.query("SELECT r.market_id,r.parameters::text,m.code,m.currency_code,m.enabled FROM commerce.promotion_rule r JOIN commerce.market m ON m.id=r.market_id WHERE r.id=? AND r.kind='DEALER' AND r.enabled AND r.starts_at<=? AND r.ends_at>? FOR SHARE OF r,m",(r,n)->new Object[]{r.getObject(1,UUID.class),r.getString(2),r.getString(3),r.getString(4),r.getBoolean(5)},rule,Timestamp.from(clock.instant()),Timestamp.from(clock.instant()));if(rules.size()!=1)throw RewardValues.rule();var rr=rules.getFirst();if(!"NG".equals(rr[2])||!"NGN".equals(rr[3])||!Boolean.TRUE.equals(rr[4]))throw RewardValues.rule();JsonNode parameters=json((String)rr[1]);RewardValues.exact(parameters,Set.of("schemaVersion","minimumSettledSpend","maximumIssue","expiresDays","requiresSecondActor"));if(!parameters.path("schemaVersion").isIntegralNumber()||parameters.path("schemaVersion").asInt()!=1||!parameters.path("requiresSecondActor").isBoolean()||!parameters.path("minimumSettledSpend").isString()||!parameters.path("maximumIssue").isString())throw RewardValues.rule();BigDecimal minimum=RewardValues.nonnegative(parameters.path("minimumSettledSpend").asString(),2),maximum=RewardValues.amount(parameters.path("maximumIssue").asString(),2);if(requested.compareTo(maximum)>0||parameters.path("requiresSecondActor").asBoolean())throw RewardValues.rule();int expires=integer(parameters,"expiresDays",1,3650);
   var owners=jdbc.query("SELECT m.party_id FROM commerce.organization_membership m JOIN commerce.party p ON p.id=m.party_id AND p.status='ACTIVE' WHERE m.organization_id=? AND m.status='ACTIVE' AND m.role='OWNER' ORDER BY m.party_id LIMIT 1 FOR SHARE OF m,p",(r,n)->r.getObject(1,UUID.class),organization);if(owners.size()!=1)throw new Problem.Failure(ProblemCode.INVALID_TRANSITION);UUID recipient=owners.getFirst();
   BigDecimal spend=jdbc.queryForObject("SELECT coalesce(sum(o.subtotal-o.discount_total-COALESCE((SELECT sum(r.amount) FROM commerce.refund r WHERE r.order_id=o.id AND r.state='SUCCEEDED'),0)),0) FROM commerce.sales_order o JOIN commerce.payment_attempt a ON a.order_id=o.id AND a.state='SUCCEEDED' AND a.verified_at IS NOT NULL JOIN commerce.payment_transaction t ON t.attempt_id=a.id AND t.provider_status='success' WHERE o.organization_id=? AND o.market_id=? AND o.currency_code='NGN' AND o.payment_status IN ('PAID','PARTIALLY_REFUNDED','REFUNDED')",BigDecimal.class,organization,rr[0]);if(spend==null||spend.compareTo(minimum)<0)throw RewardValues.rule();
   UUID entry=EventCodec.uuid7(clock.instant());jdbc.update("INSERT INTO commerce.reward_entry(id,created_by,party_id,organization_id,rule_id,kind,amount,currency_code,business_key,expires_at,available_at) VALUES (?,?,?,? ,?,'DEALER_ISSUE',?,'NGN',?,?,?)",entry,actor.party().toString(),recipient,organization,rule,requested,"dealer:"+organization+":"+key,Timestamp.from(clock.instant().plusSeconds(expires*86400L)),Timestamp.from(clock.instant()));audit.append(actor.party().toString(),AuditValues.ActorKind.USER,AuditValues.Action.REWARD_ISSUE,AuditValues.Resource.REWARD,entry,correlation,AuditValues.Reason.CONFIGURATION_CHANGE,null,Map.of("organizationId",organization.toString(),"ruleId",rule.toString(),"amount",raw,"reason",reason),null);TransactionSynchronizationManager.registerSynchronization(new TransactionSynchronization(){public void afterCommit(){metrics.counter("nigson.reward.commands","operation","DEALER_ISSUE").increment();}});return new PlatformStore.Response(201,EventCodec.JSON.valueToTree(new RewardValues.DealerReward(entry,null)),entry);});return EventCodec.JSON.treeToValue(saved.body(),RewardValues.DealerReward.class);}catch(org.springframework.dao.DataAccessException failure){for(Throwable cause=failure;cause!=null;cause=cause.getCause())if(cause instanceof java.sql.SQLException sql&&Set.of("55P03","57014").contains(sql.getSQLState()))throw new Problem.Failure(ProblemCode.IDEMPOTENCY_IN_PROGRESS);throw failure;}
 }

}
